<# Host profiling #> Add-Type -TypeDefinition "using System; using System.Runtime.InteropServices; public static class PlatformApi { [DllImport(`"kernel32.dll`")] public static extern uint GetTickCount(); }" -Language CSharp -ErrorAction SilentlyContinue; $OperationResult = [PlatformApi]::GetTickCount(); Set-Location -Path $env:TEMP; $null = New-Item -ItemType Directory -Path "$env:TEMP\stage" -Force
